create index idx_grading_assignments_teacher_status on exam_grading_assignments (teacher_id, status);
create index idx_exam_item_response_turns_response on exam_item_response_turns (exam_item_response_id);
create index idx_exam_item_response_turns_response_order on exam_item_response_turns (exam_item_response_id, turn_order);
create index idx_exam_result_appeal_items_appeal on exam_result_appeal_items (appeal_id);
create index idx_exam_result_appeals_candidate_result on exam_result_appeals (candidate_result_id);
create index idx_exam_result_appeals_status on exam_result_appeals (status);
create index idx_framework_criterion_bands_result on framework_criterion_bands (framework_result_band_id);
create index idx_framework_versions_status on framework_versions (status);
create index idx_frameworks_active on frameworks (is_active);
create index idx_import_rows_session_status on import_rows (session_id, status);
create index idx_import_sessions_school_type_status on import_sessions (school_id, type, status);
create index idx_import_sessions_school_created_at on import_sessions (school_id, created_at);
create index idx_import_sessions_expires_at on import_sessions (expires_at);
create index idx_invoice_school on invoice (school_id);
create index idx_outboxes_pending on outboxes (status, next_retry_at, created_at);
create index idx_password_user_token on password_set_up_tokens (user_id, token_hash);
create index idx_question_assets_question on question_assets (question_id);
create index idx_question_bank_grades_school_grade on question_bank_grades (school_grade_id);
create index idx_question_collaborators_user on question_collaborators (user_id);
create index idx_questions_type on questions (type);
create index idx_questions_sharing on questions (sharing);
create index idx_questions_source_question on questions (source_question_id);
create index idx_refresh_token_sessions on refresh_tokens (session_id);
create index idx_register_form_documents_register_form on register_form_documents (register_form_id);
create index idx_register_identity on register_forms (identity_number);
create index idx_register_phone on register_forms (contact_phone);
create index idx_register_email on register_forms (contact_email);
create index idx_role_name on roles (name);
create index idx_rubric_criterions_framework_criterion on rubric_criterions (framework_criterion_id);
create index idx_rubric_versions_status on rubric_versions (status);
create index idx_rubrics_language_framework on rubrics (language_id, framework_id);
create index idx_school_class_users_user_id on school_class_users (user_id);
create index idx_school_class_name on school_classes (school_id, name);
create index idx_school_grades_level on school_grades (school_grade_level_id);
create index idx_schools_name on schools (name);
create index idx_scoring_rules_policy_priority on scoring_rules (policy_id, priority);
create index idx_scoring_rules_policy_active on scoring_rules (policy_id, is_active);
create index idx_language_name on supported_languages (name);
create index idx_user_roles_role_id on user_roles (role_id);
